static ScheduledFuture<?> scheduleRepeatedTimes(ScheduledExecutorService sched, Runnable task, long periodMs, int repeats) {
    AtomicInteger count = new AtomicInteger(0);
    ScheduledFuture<?>[] ref = new ScheduledFuture<?>[1];
    ref[0] = sched.scheduleAtFixedRate(() -> { task.run(); if (count.incrementAndGet() >= repeats) ref[0].cancel(false); }, 0, periodMs, TimeUnit.MILLISECONDS);
    return ref[0];
}
