static void scheduleUntilCondition(ScheduledExecutorService sched, Runnable task, long periodMs, Supplier<Boolean> stopCondition) {
    ScheduledFuture<?>[] ref = new ScheduledFuture<?>[1];
    ref[0] = sched.scheduleAtFixedRate(() -> { task.run(); if (stopCondition.get()) ref[0].cancel(false); }, 0, periodMs, TimeUnit.MILLISECONDS);
}
