class RefreshableCache {
    String value = "poczatkowa";
    ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    void refresh(String v) { lock.writeLock().lock(); try { value = v; } finally { lock.writeLock().unlock(); } }
    String get() { lock.readLock().lock(); try { return value; } finally { lock.readLock().unlock(); } }
}
RefreshableCache cache = new RefreshableCache();
